create table if not exists `sb_meta` (`k` varchar(64) not null, `v` varchar(255) not null, constraint `sb_meta_pk` primary key (`k`));
create table if not exists `sb_players` (`uuid` binary(16) not null, `last_name` varchar(32) not null, `last_name_lower` varchar(32) not null, `first_seen` bigint not null, `last_seen` bigint not null, `last_address` varbinary(16) null, constraint `sb_players_pk` primary key (`uuid`), constraint `sb_players_last_address_ck` check ((`last_address` is null or octet_length(`last_address`) in (4, 16))));
create table if not exists `sb_player_names` (`uuid` binary(16) not null, `name` varchar(32) not null, `name_lower` varchar(32) not null, `first_seen` bigint not null, `last_seen` bigint not null, constraint `sb_player_names_pk` primary key (`uuid`, `name_lower`), constraint `sb_player_names_player_fk` foreign key (`uuid`) references `sb_players` (`uuid`) on delete cascade);
create table if not exists `sb_player_addresses` (`uuid` binary(16) not null, `address` varbinary(16) not null, `first_seen` bigint not null, `last_seen` bigint not null, `last_server` varchar(64) null, constraint `sb_player_addresses_pk` primary key (`uuid`, `address`), constraint `sb_player_addresses_player_fk` foreign key (`uuid`) references `sb_players` (`uuid`) on delete cascade, constraint `sb_player_addresses_address_ck` check (octet_length(`address`) in (4, 16)));
create table if not exists `sb_scopes` (`id` int not null auto_increment, `kind` smallint not null, `value` varchar(64) not null, constraint `sb_scopes_pk` primary key (`id`), constraint `sb_scopes_identity_uq` unique (`kind`, `value`), constraint `sb_scopes_global_ck` check (((`kind` = 0 and `value` = '*') or (`kind` <> 0 and `value` <> '*'))));
create table if not exists `sb_victims` (`id` bigint not null auto_increment, `kind` smallint not null, `uuid` binary(16) not null, `address` varbinary(16) not null, `prefix_length` smallint not null, constraint `sb_victims_pk` primary key (`id`), constraint `sb_victims_identity_uq` unique (`kind`, `uuid`, `address`, `prefix_length`), constraint `sb_victims_shape_ck` check (((`kind` = 0 and octet_length(`address`) = 0 and `prefix_length` = 0) or (`kind` in (1, 2) and ((octet_length(`address`) = 4 and `prefix_length` between 32 and 32) or (octet_length(`address`) = 16 and `prefix_length` between 128 and 128))) or (`kind` = 3 and ((octet_length(`address`) = 4 and `prefix_length` between 1 and 32) or (octet_length(`address`) = 16 and `prefix_length` between 1 and 128))))));
create table if not exists `sb_kinds` (`id` varchar(64) not null, `display_name` varchar(64) not null, `base_type` smallint not null, `shadow` smallint not null, `strictness` smallint null, `default_scope_id` int null, `address_mode` smallint not null, `permanent_only` smallint not null, `required_evidence` varchar(1024) not null, `built_in` smallint not null, `version` bigint not null, `created_at` bigint not null, `updated_at` bigint not null, constraint `sb_kinds_pk` primary key (`id`), constraint `sb_kinds_scope_fk` foreign key (`default_scope_id`) references `sb_scopes` (`id`), constraint `sb_kinds_version_ck` check (`version` >= 1));
create table if not exists `sb_templates` (`id` int not null auto_increment, `name` varchar(64) not null, `kind` varchar(64) not null, `type` smallint not null, `reason` varchar(1024) not null, `required_evidence` varchar(1024) not null, `capture_evidence` varchar(1024) not null, `ladder_expiry_ms` bigint null, `address_shared` smallint not null, `permission_required` smallint not null, `actions` varchar(4096) not null, `version` bigint not null, `created_at` bigint not null, `updated_at` bigint not null, constraint `sb_templates_pk` primary key (`id`), constraint `sb_templates_name_uq` unique (`name`), constraint `sb_templates_version_ck` check (`version` >= 1));
create table if not exists `sb_template_steps` (`template_id` int not null, `position` smallint not null, `duration_ms` bigint null, `actions` varchar(4096) not null, constraint `sb_template_steps_pk` primary key (`template_id`, `position`), constraint `sb_template_steps_template_fk` foreign key (`template_id`) references `sb_templates` (`id`) on delete cascade, constraint `sb_template_steps_step_ck` check ((`position` >= 0 and (`duration_ms` is null or `duration_ms` > 0))));
create table if not exists `sb_template_groups` (`id` int not null auto_increment, `name` varchar(64) not null, `version` bigint not null, constraint `sb_template_groups_pk` primary key (`id`), constraint `sb_template_groups_name_uq` unique (`name`), constraint `sb_template_groups_version_ck` check (`version` >= 1));
create table if not exists `sb_template_group_members` (`group_id` int not null, `template_id` int not null, `weight` smallint not null, constraint `sb_template_group_members_pk` primary key (`group_id`, `template_id`), constraint `sb_template_group_members_group_fk` foreign key (`group_id`) references `sb_template_groups` (`id`) on delete cascade, constraint `sb_template_group_members_template_fk` foreign key (`template_id`) references `sb_templates` (`id`) on delete cascade, constraint `sb_template_group_members_weight_ck` check (`weight` >= 1));
create table if not exists `sb_punishments` (`id` bigint not null auto_increment, `type` smallint not null, `kind` varchar(64) not null, `shadow` smallint not null, `strictness` smallint null, `victim_id` bigint not null, `scope_id` int not null, `reason` varchar(1024) not null, `operator_kind` smallint not null, `operator_uuid` binary(16) null, `operator_name` varchar(64) not null, `source` varchar(64) not null, `created_at` bigint not null, `expires_at` bigint null, `origin_server` varchar(64) null, `visibility` smallint not null, `template` varchar(64) null, `template_step` smallint null, `ended_at` bigint null, `end_kind` smallint null, `revoker_kind` smallint null, `revoker_uuid` binary(16) null, `revoker_name` varchar(64) null, `revoker_source` varchar(64) null, `revoke_reason` varchar(1024) null, `voided_at` bigint null, `voider_kind` smallint null, `voider_uuid` binary(16) null, `voider_name` varchar(64) null, `voider_source` varchar(64) null, `void_reason` varchar(1024) null, `version` bigint not null, `external_id` varchar(128) null, `acknowledged` smallint not null, constraint `sb_punishments_pk` primary key (`id`), constraint `sb_punishments_external_id_uq` unique (`external_id`), constraint `sb_punishments_victim_fk` foreign key (`victim_id`) references `sb_victims` (`id`), constraint `sb_punishments_scope_fk` foreign key (`scope_id`) references `sb_scopes` (`id`), constraint `sb_punishments_expiry_ck` check ((`expires_at` is null or `expires_at` > `created_at`)), constraint `sb_punishments_kick_ck` check ((`type` <> 3 or `expires_at` is null)), constraint `sb_punishments_operator_ck` check ((`operator_kind` <> 1 or `operator_uuid` is not null)), constraint `sb_punishments_end_ck` check (((`ended_at` is null and `end_kind` is null and `revoker_kind` is null) or (`ended_at` is not null and `end_kind` is not null))), constraint `sb_punishments_void_ck` check (((`voided_at` is null and `voider_kind` is null) or (`voided_at` is not null and `voider_kind` is not null))), constraint `sb_punishments_version_ck` check (`version` >= 1));
create table if not exists `sb_active_punishments` (`punishment_id` bigint not null, `type` smallint not null, `victim_id` bigint not null, `scope_id` int not null, `expires_at` bigint null, `exclusivity_slot` bigint not null, constraint `sb_active_punishments_pk` primary key (`punishment_id`), constraint `sb_active_punishments_exclusive_uq` unique (`type`, `victim_id`, `scope_id`, `exclusivity_slot`), constraint `sb_active_punishments_punishment_fk` foreign key (`punishment_id`) references `sb_punishments` (`id`) on delete cascade, constraint `sb_active_punishments_victim_fk` foreign key (`victim_id`) references `sb_victims` (`id`), constraint `sb_active_punishments_scope_fk` foreign key (`scope_id`) references `sb_scopes` (`id`), constraint `sb_active_punishments_slot_ck` check (((`type` = 2 and `exclusivity_slot` > 0) or (`type` in (0, 1) and `exclusivity_slot` = 0))));
create table if not exists `sb_punishment_evidence` (`punishment_id` bigint not null, `uri` varchar(512) not null, `added_by_kind` smallint not null, `added_by_uuid` binary(16) null, `added_by_name` varchar(64) not null, `added_by_source` varchar(64) not null, `added_at` bigint not null, constraint `sb_punishment_evidence_pk` primary key (`punishment_id`, `uri`), constraint `sb_punishment_evidence_punishment_fk` foreign key (`punishment_id`) references `sb_punishments` (`id`) on delete cascade);
create table if not exists `sb_audit_log` (`id` bigint not null auto_increment, `at` bigint not null, `actor_kind` smallint not null, `actor_uuid` binary(16) null, `actor_name` varchar(64) not null, `source` varchar(64) not null, `action` smallint not null, `subject_type` smallint not null, `subject_id` varchar(64) not null, `old_value` longtext null, `new_value` longtext null, constraint `sb_audit_log_pk` primary key (`id`));
create table if not exists `sb_allowed_players` (`uuid` binary(16) not null, `added_by_kind` smallint not null, `added_by_uuid` binary(16) null, `added_by_name` varchar(64) not null, `added_by_source` varchar(64) not null, `added_at` bigint not null, `note` varchar(256) null, constraint `sb_allowed_players_pk` primary key (`uuid`));
create table if not exists `sb_allowed_addresses` (`address` varbinary(16) not null, `added_by_kind` smallint not null, `added_by_uuid` binary(16) null, `added_by_name` varchar(64) not null, `added_by_source` varchar(64) not null, `added_at` bigint not null, `note` varchar(256) null, constraint `sb_allowed_addresses_pk` primary key (`address`));
create table if not exists `sb_lockdowns` (`scope_id` int not null, `reason` varchar(1024) not null, `started_by_kind` smallint not null, `started_by_uuid` binary(16) null, `started_by_name` varchar(64) not null, `started_by_source` varchar(64) not null, `started_at` bigint not null, `ends_at` bigint null, constraint `sb_lockdowns_pk` primary key (`scope_id`), constraint `sb_lockdowns_scope_fk` foreign key (`scope_id`) references `sb_scopes` (`id`) on delete cascade);
create table if not exists `sb_sync_messages` (`id` bigint not null auto_increment, `created_at` bigint not null, `payload` varbinary(16384) not null, constraint `sb_sync_messages_pk` primary key (`id`));
create table if not exists `sb_ban_waves` (`id` bigint not null auto_increment, `name` varchar(64) not null, `status` smallint not null, `scheduled_at` bigint null, `created_by_kind` smallint not null, `created_by_uuid` binary(16) null, `created_by_name` varchar(64) not null, `created_by_source` varchar(64) not null, `created_at` bigint not null, `released_at` bigint null, `version` bigint not null, constraint `sb_ban_waves_pk` primary key (`id`), constraint `sb_ban_waves_version_ck` check (`version` >= 1));
create table if not exists `sb_ban_wave_entries` (`id` bigint not null auto_increment, `wave_id` bigint not null, `draft` longtext not null, `added_by_kind` smallint not null, `added_by_uuid` binary(16) null, `added_by_name` varchar(64) not null, `added_by_source` varchar(64) not null, `added_at` bigint not null, `result` longtext null, `punishment_id` bigint null, constraint `sb_ban_wave_entries_pk` primary key (`id`), constraint `sb_ban_wave_entries_wave_fk` foreign key (`wave_id`) references `sb_ban_waves` (`id`) on delete cascade, constraint `sb_ban_wave_entries_punishment_fk` foreign key (`punishment_id`) references `sb_punishments` (`id`) on delete set null);
create table if not exists `sb_appeals` (`id` bigint not null auto_increment, `punishment_id` bigint not null, `appellant` binary(16) not null, `message` varchar(2000) not null, `created_at` bigint not null, `status` smallint not null, `outcome` smallint null, `decided_by_kind` smallint null, `decided_by_uuid` binary(16) null, `decided_by_name` varchar(64) null, `decided_by_source` varchar(64) null, `decided_at` bigint null, `note` varchar(1024) null, `version` bigint not null, constraint `sb_appeals_pk` primary key (`id`), constraint `sb_appeals_punishment_fk` foreign key (`punishment_id`) references `sb_punishments` (`id`) on delete cascade, constraint `sb_appeals_decision_ck` check (((`status` = 0 and `decided_at` is null) or (`status` <> 0 and `decided_at` is not null))), constraint `sb_appeals_version_ck` check (`version` >= 1));
create table if not exists `sb_setting_overrides` (`k` varchar(255) not null, `v` longtext not null, `updated_at` bigint not null, constraint `sb_setting_overrides_pk` primary key (`k`));
create table if not exists `sb_message_overrides` (`locale` varchar(16) not null, `k` varchar(128) not null, `text` longtext not null, `updated_at` bigint not null, constraint `sb_message_overrides_pk` primary key (`locale`, `k`));
create index `sb_players_last_name_ix` on `sb_players`(`last_name_lower`);
create index `sb_player_names_name_ix` on `sb_player_names`(`name_lower`, `last_seen`);
create index `sb_player_addresses_address_ix` on `sb_player_addresses`(`address`, `last_seen`);
create index `sb_victims_uuid_ix` on `sb_victims`(`uuid`);
create index `sb_victims_address_ix` on `sb_victims`(`address`);
create index `sb_punishments_victim_ix` on `sb_punishments`(`victim_id`, `type`, `created_at`);
create index `sb_punishments_operator_ix` on `sb_punishments`(`operator_uuid`, `created_at`);
create index `sb_punishments_created_ix` on `sb_punishments`(`created_at`);
create index `sb_punishments_template_ix` on `sb_punishments`(`template`, `victim_id`);
create index `sb_punishments_revoker_ix` on `sb_punishments`(`revoker_uuid`, `ended_at`);
create index `sb_active_punishments_victim_ix` on `sb_active_punishments`(`victim_id`);
create index `sb_active_punishments_expiry_ix` on `sb_active_punishments`(`expires_at`);
create index `sb_audit_log_subject_ix` on `sb_audit_log`(`subject_type`, `subject_id`);
create index `sb_audit_log_at_ix` on `sb_audit_log`(`at`);
create index `sb_audit_log_actor_ix` on `sb_audit_log`(`actor_uuid`, `at`);
create index `sb_sync_messages_created_ix` on `sb_sync_messages`(`created_at`);
create index `sb_ban_wave_entries_wave_ix` on `sb_ban_wave_entries`(`wave_id`);
create index `sb_appeals_punishment_ix` on `sb_appeals`(`punishment_id`);
create index `sb_appeals_status_ix` on `sb_appeals`(`status`, `created_at`);
create index `sb_appeals_appellant_ix` on `sb_appeals`(`appellant`);
